<script setup>
import { Link } from '@inertiajs/vue3';
import VendorLayout from '../../../../Layouts/VendorLayout.vue';
import { appUrl } from '../../../../appUrl';
defineProps({ bookings: Object, properties: Array, statuses: Array, paymentStatuses: Array });
const query = new URLSearchParams(window.location.search);
const filter = Object.fromEntries(['booking_number', 'property_id', 'status', 'payment_status', 'check_in_from', 'check_in_to'].map((key) => [key, query.get(key) || '']));
function applyFilters() { window.location.href = `${appUrl('/vendor/hotel/bookings')}?${new URLSearchParams(Object.entries(filter).filter(([, value]) => value)).toString()}`; }
</script>
<template><VendorLayout><div class="container-fluid py-4"><h1>Hotel Bookings</h1><form class="card card-body mb-3" @submit.prevent="applyFilters"><div class="row g-2"><div class="col-md-3"><input v-model="filter.booking_number" class="form-control" placeholder="Booking number" /></div><div class="col-md-3"><select v-model="filter.property_id" class="form-select"><option value="">All properties</option><option v-for="property in properties" :key="property.id" :value="property.id">{{ property.name }}</option></select></div><div class="col-md-2"><select v-model="filter.status" class="form-select"><option value="">Status</option><option v-for="status in statuses" :key="status.value" :value="status.value">{{ status.label }}</option></select></div><div class="col-md-2"><select v-model="filter.payment_status" class="form-select"><option value="">Payment</option><option v-for="status in paymentStatuses" :key="status.value" :value="status.value">{{ status.label }}</option></select></div><div class="col-md-2"><input v-model="filter.check_in_from" type="date" class="form-control" /></div><div class="col-md-2"><input v-model="filter.check_in_to" type="date" class="form-control" /></div><div class="col-md-2"><button class="btn btn-outline-primary">Apply</button><a class="btn btn-link" :href="appUrl('/vendor/hotel/bookings')">Clear</a></div></div></form><div v-for="booking in bookings.data" :key="booking.id" class="card p-3 mb-2"><Link :href="appUrl(`/vendor/hotel/bookings/${booking.id}`)">{{ booking.booking_number }}</Link><span>{{ booking.property?.name }}</span><span>{{ booking.check_in }} → {{ booking.check_out }} · {{ booking.status }} · {{ booking.payment_status }}</span></div></div></VendorLayout></template>
